// ─── File: DecisionDemo.java ───
// Single runnable file with multiple top-level, package-private classes.

import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Handler;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class DecisionDemo {

    private static final Logger log = Logger.getLogger(DecisionDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger rootLogger = Logger.getLogger("");
        for (Handler handler : rootLogger.getHandlers()) {
            rootLogger.removeHandler(handler);
        }
        ConsoleHandler consoleHandler = new ConsoleHandler();
        consoleHandler.setFormatter(new BankLogFormatter());
        consoleHandler.setLevel(Level.ALL);
        rootLogger.addHandler(consoleHandler);
        rootLogger.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "Deciding under incomplete information during an incident at " + BANK_NAME);

        List<DecisionOption> options = new ArrayList<>();
        // Worst-case cost if we are wrong: keep running could double-charge many accounts.
        options.add(new DecisionOption("Keep running", 1000000, false));
        options.add(new DecisionOption("Throttle transfers", 200000, true));
        options.add(new DecisionOption("Pause transfers", 50000, true));

        DecisionHelper helper = new DecisionHelper(true);
        DecisionOption chosen = helper.recommend(options);

        log.info(() -> "Recommended action under uncertainty: " + chosen.getName()
                + " (worst-case cost " + chosen.getWorstCaseCost()
                + ", reversible=" + chosen.isReversible() + ")");
        log.info("Will revisit the decision as soon as the blast radius is known.");
    }
}

// ─── Would be in model/DecisionOption.java in a real project ───
class DecisionOption {
    private final String name;
    private final long worstCaseCost;   // in rupees if this choice turns out wrong
    private final boolean reversible;

    DecisionOption(String name, long worstCaseCost, boolean reversible) {
        this.name = name;
        this.worstCaseCost = worstCaseCost;
        this.reversible = reversible;
    }

    String getName() { return name; }
    long getWorstCaseCost() { return worstCaseCost; }
    boolean isReversible() { return reversible; }
}

// ─── Would be in helper/DecisionHelper.java in a real project ───
class DecisionHelper {
    private static final Logger log = Logger.getLogger(DecisionHelper.class.getName());
    private final boolean preferReversible;

    DecisionHelper(boolean preferReversible) {
        this.preferReversible = preferReversible;
    }

    // Choose the lowest worst-case cost; break ties toward reversible options.
    DecisionOption recommend(List<DecisionOption> options) {
        DecisionOption best = null;
        for (DecisionOption o : options) {
            log.fine(() -> "Option " + o.getName() + " worst-case=" + o.getWorstCaseCost()
                    + " reversible=" + o.isReversible());
            if (best == null || isBetter(o, best)) {
                best = o;
            }
        }
        return best;
    }

    private boolean isBetter(DecisionOption candidate, DecisionOption current) {
        if (candidate.getWorstCaseCost() < current.getWorstCaseCost()) {
            return true;
        }
        if (candidate.getWorstCaseCost() == current.getWorstCaseCost()
                && preferReversible && candidate.isReversible() && !current.isReversible()) {
            return true;
        }
        return false;
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
                record.getMillis(),
                record.getLevel().getName(),
                record.getSourceClassName() != null
                        ? record.getSourceClassName().substring(
                                record.getSourceClassName().lastIndexOf('.') + 1)
                        : "Unknown",
                record.getMessage());
    }
}
